  assert.equal(report.originalMediaPreserved, true);
  assert.equal(report.productionRegistrationAccepted, true);
  assert.match(report.originalSha256, /^[a-f0-9]{64}$/);
  const ids = new Set();
  for (const kind of ["missing", "installed", "replaced", "repeat"]) {
