}
impl IpcWorkObserver {
    fn new(started: std::time::Instant) -> Self {
        Self {
            state: std::sync::Mutex::new(IpcWorkState {
                started,
                commands: Default::default(),
            }),
            dropped: Default::default(),
        }
    }

    fn record(
