        now: std::time::Instant,
        emit: impl FnOnce(IpcWorkSnapshot),
    ) {
        if !handled {
            return;
        }
        let Ok(mut state) = self.state.try_lock() else {
            self.dropped
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
