            window_ms: elapsed.as_millis(),
            commands: std::mem::take(&mut state.commands),
            dropped: self.dropped.swap(0, std::sync::atomic::Ordering::Relaxed),
        };
        state.started = now;
        drop(state);
        emit(snapshot);
    }
}

