    pub(crate) fn status_in(
        &self,
        conversation: ConversationId,
        id: EventId,
    ) -> Option<DeliveryStatus> {
        let in_scope = self.messages.get(&id).is_some_and(|m| m.conversation == conversation)
            || self.completed.get(&id).is_some_and(|m| m.conversation == conversation)
            || self.pending.iter().any(|tx| matches!(tx.body(), DeliveryTransaction::Outgoing { message, .. } | DeliveryTransaction::OutgoingManifest { message, .. } if message.logical_id == id && message.conversation == conversation));
        in_scope.then(|| self.status(id)).flatten()
    }

    pub(crate) fn cancellation_rows(&self) -> Vec<(ConversationId, EventId, u64)> {
        self.messages
            .values()
            .map(|m| (m.conversation, m.logical_id, m.wall_clock))
            .chain(
                self.completed
                    .values()
                    .map(|m| (m.conversation, m.logical_id, m.wall_clock)),
            )
            .chain(
                self.receipts
                    .values()
                    .map(|m| (m.conversation, m.logical_id, m.wall_clock)),
            )
            .chain(
                self.completed_receipts
                    .values()
                    .map(|m| (m.conversation, m.logical_id, m.wall_clock)),
            )
            .chain(
                self.files
                    .values()
                    .filter(|file| file.destinations.iter().any(|d| d.active))
                    .map(|file| (file.conversation, file.id, file.wall_clock)),
            )
            .collect()
    }

    /// Replay strictly in journal order. Ratchets cannot be used for unrelated
    pub fn delivery_status(&self, id: EventId) -> Option<DeliveryStatus> {
        self.delivery
            .lock()
            .expect("delivery lock not poisoned")
            .status(id)
    }

    /// Confirmed chunks across the recipient account's devices. Local staging and
    /// self-device replication are excluded from the sender's upload percentage.
    pub fn outgoing_file_progress(&self, id: EventId) -> Option<super::OutgoingFileProgress> {
        let delivery = self.delivery.lock().expect("delivery lock not poisoned");
        let card = delivery.file_card(id)?;
        let own_account = self.account_id();
        let recipients = card
            .destinations
            .iter()
            .filter(|d| d.binding.account.as_deref() != Some(own_account.as_str()))
