//! Bounded latency estimates for authenticated route attempts.

use std::{
    collections::HashMap,
    net::SocketAddr,
    time::{Duration, Instant},
};

const MAX_ROUTES: usize = 256;

/// Successful authenticated endpoints are advisory, just like route timings.
/// Retain the most recently successful devices within the same hint budget.
#[derive(Default)]
pub(super) struct PreferredRoutes {
    entries: HashMap<String, (SocketAddr, u64)>,
    sequence: u64,
}

impl PreferredRoutes {
    pub(super) fn insert(&mut self, device: String, address: SocketAddr) {
        self.sequence = self.sequence.wrapping_add(1);
        if !self.entries.contains_key(&device) && self.entries.len() >= MAX_ROUTES {
            let oldest = self
                .entries
                .iter()
                .min_by_key(|(_, (_, updated))| *updated)
                .map(|(device, _)| device.clone());
            if let Some(oldest) = oldest {
                self.entries.remove(&oldest);
            }
        }
        self.entries.insert(device, (address, self.sequence));
    }

    pub(super) fn get(&self, device: &str) -> Option<&SocketAddr> {
        self.entries.get(device).map(|(address, _)| address)
    }

    #[cfg(test)]
    pub(super) fn len(&self) -> usize {
        self.entries.len()
    }
}
const MIN_DEADLINE: Duration = Duration::from_secs(3);
const COLD_DEADLINE: Duration = Duration::from_secs(10);
pub(super) const MAX_AUTHENTICATION_DEADLINE: Duration = Duration::from_secs(20);
const MAX_DEADLINE: Duration = MAX_AUTHENTICATION_DEADLINE;
const MIN_CONTROL_DEADLINE: Duration = Duration::from_secs(15);
pub(super) const MAX_CONTROL_DEADLINE: Duration = Duration::from_secs(60);

struct Estimate {
    observed_at: Instant,
    authentication: Option<Sample>,
    control: Option<Sample>,
    backoff: Duration,
    control_backoff: Duration,
    updated: u64,
    authentication_updated: u64,
    control_updated: u64,
}

struct Sample {
    mean_ms: f64,
    variation_ms: f64,
}

impl Sample {
    fn observe(slot: &mut Option<Self>, elapsed: Duration) {
        let sample = elapsed.as_secs_f64().max(0.001) * 1000.0;
        if let Some(e) = slot {
            e.variation_ms = 0.75 * e.variation_ms + 0.25 * (sample - e.mean_ms).abs();
            e.mean_ms = 0.875 * e.mean_ms + 0.125 * sample;
        } else {
            *slot = Some(Self {
                mean_ms: sample,
                variation_ms: sample / 2.0,
            });
        }
    }

    fn margin(&self) -> Duration {
        Duration::from_secs_f64((self.mean_ms + 4.0 * self.variation_ms) / 1000.0)
    }
}

